import { useEffect, useState, useMemo, useCallback, useRef } from "react";
import { useRouter } from "next/router";
import Head from "next/head";
import AppLayout, { useUser } from "@/components/AppLayout";
import { supabase } from "@/lib/supabase";
import { 
  PieChart, Pie, Cell, BarChart, Bar, AreaChart, Area, 
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { getISTDateRange } from "@/lib/dateUtils";
import MemberPerformanceTable from '@/components/shared/MemberPerformanceTable';
import { aggregatePerformance, SharedPerformanceStats } from "@/lib/performanceUtils";

/**
 * TeamDetails Page Refactor
 * Goal: Improve performance, request safety, and data accuracy without UI/Behavior changes.
 */
export default function TeamDetails() {
  const router = useRouter();
  const { id } = router.query;
  const { user, mounted } = useUser();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  // RAW Data States
  const [team, setTeam] = useState<any>(null);
  const [members, setMembers] = useState<any[]>([]);
  const [rawLogs, setRawLogs] = useState<any[]>([]);
  const [rawCustomers, setRawCustomers] = useState<any[]>([]);
  const [rawSyncMeta, setRawSyncMeta] = useState<any[]>([]);
  const [rawCallLogs, setRawCallLogs] = useState<any[]>([]);
  const [rawSessions, setRawSessions] = useState<any[]>([]);
  const [dateFilter, setDateFilter] = useState("today");

  // REPLACING LOCAL STATES WITH SHARED UTILITY OUTPUT
  const [memberStatsMap, setMemberStatsMap] = useState<Record<string, SharedPerformanceStats>>({});

  const COLORS = ['#4b33e8', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#6366f1'];
  const abortControllerRef = useRef<AbortController | null>(null);

  const getDateRange = useCallback((filter: string) => {
    return getISTDateRange(filter);
  }, []);

  const fetchTeamData = useCallback(async () => {
    if (!id || Array.isArray(id)) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);
      
      const { data: teamData, error: teamError } = await supabase
        .from('teams')
        .select(`id, name, is_active, members, leader_id, organization:organizations(company_name), leader:user_profiles!leader_id(user_name)`)
        .eq('id', id as string)
        .maybeSingle();
      
      if (teamError) throw new Error(`Failed to fetch team details: ${teamError.message}`);
      if (!teamData) { setError("Team not found or access denied."); setLoading(false); return; }
      setTeam(teamData);

      const memberIds = Array.isArray(teamData.members) ? teamData.members : [];
      if (memberIds.length === 0) { setMembers([]); setRawLogs([]); setLoading(false); return; }

      const { data: membersData, error: membersError } = await supabase
        .from('user_profiles')
        .select('user_id, user_name, employee_id, profile_pic_url, status, last_online')
        .in('user_id', memberIds)
        .eq('status', 'active');

      if (membersError) throw new Error(`Members fetch failed: ${membersError.message}`);
      
      const validMembers = (membersData || []).sort((a: any, b: any) => (a.user_name || '').localeCompare(b.user_name || ''));
      setMembers(validMembers);

      const employeeIds = validMembers.map(m => m.employee_id).filter(id => !!id);
      const { start, end } = getDateRange(dateFilter);
      
      const [customersRes, historyRes, syncRes, callLogsRes, sessionRes] = await Promise.all([
         supabase.from('customers').select('assigned_to, next_called_at, created_at, customer_details, disposition').in('assigned_to', memberIds),
         supabase.from('call_history').select('employee_id, duration, call_type, timestamp, device_id, number, name').in('employee_id', employeeIds).gte('timestamp', start).lte('timestamp', end).limit(50000),
         supabase.from('sync_meta').select('employee_id, on_call, is_personal, last_seen').in('employee_id', employeeIds),
         supabase.from('call_logs').select('agent_id, duration, is_connected, created_at, disposition').in('agent_id', memberIds).gte('created_at', start).lte('created_at', end).limit(50000),
         supabase.from('user_sessions').select('user_id, last_accessed_at').in('user_id', memberIds).order('last_accessed_at', { ascending: false })
      ]);

      if (historyRes.error) throw new Error(`History fetch failed: ${historyRes.error.message}`);

      // Process sessions
      const latestSessions: any[] = []; const seenUsers = new Set();
      (sessionRes.data || []).forEach(s => { if (!seenUsers.has(s.user_id)) { latestSessions.push(s); seenUsers.add(s.user_id); } });

      // USE SHARED UTILITY FOR AGGREGATION
      const { statsMap } = aggregatePerformance(
        validMembers,
        historyRes.data || [],
        callLogsRes.data || [],
        syncRes.data || [],
        latestSessions,
        customersRes.data || []
      );

      setMemberStatsMap(statsMap);
      setRawLogs(historyRes.data || []); // Still used for charts below
      setRawCustomers(customersRes.data || []); // Still used for charts below
      setRawCallLogs(callLogsRes.data || []);
      setRawSyncMeta(syncRes.data || []);
      setRawSessions(latestSessions);

    } catch (err: any) {
      console.error("Fatal Error in fetchTeamData:", err);
      setError(err.message || "Failed to load team analytics.");
    } finally {
      setLoading(false);
    }
  }, [id, dateFilter, getDateRange]);

  useEffect(() => {
    if (router.isReady && id && mounted && user) fetchTeamData();
  }, [router.isReady, id, mounted, user, fetchTeamData]);

  useEffect(() => {
    if (router.isReady && id && mounted && user) {
      const interval = setInterval(() => fetchTeamData(), 30000);
      return () => clearInterval(interval);
    }
  }, [router.isReady, id, mounted, user, fetchTeamData]);

  // Derived Computations for Charts (Maintained for UI continuity)
  const chartsData = useMemo(() => {
    if (!members.length) return { outcome: [], hourly: [], disposition: [] };
    
    const outcomeCounts: Record<string, number> = {};
    rawLogs.forEach(l => {
      const type = (l.call_type || 'Unknown').toLowerCase();
      let status = 'Unknown';
      if (type.includes('outgoing')) status = 'Outgoing';
      else if (type.includes('incoming')) status = 'Incoming';
      else if (type.includes('missed')) status = 'Missed';
      else if (type.includes('reject')) status = 'Rejected';
      outcomeCounts[status] = (outcomeCounts[status] || 0) + 1;
    });

    const hourLabels: string[] = [];
    for (let i = 8; i <= 20; i += 2) hourLabels.push(`${i > 12 ? i - 12 : i}${i >= 12 ? 'pm' : 'am'} - ${i + 2 > 12 ? i + 2 - 12 : i + 2}${i + 2 >= 12 ? 'pm' : 'am'}`);
    const hourlyMap = Object.fromEntries(hourLabels.map(l => [l, 0]));
    rawLogs.forEach(l => {
      const h = new Date(l.timestamp).getHours();
      for (let i = 8; i <= 20; i += 2) { if (h >= i && h < i + 2) { hourlyMap[hourLabels[(i - 8) / 2]]++; break; } }
    });

    const dispCounts: Record<string, number> = {};
    rawCustomers.forEach(c => { const d = c.disposition || 'Fresh'; dispCounts[d] = (dispCounts[d] || 0) + 1; });

    return {
      outcome: Object.entries(outcomeCounts).map(([name, value]) => ({ name, value })),
      hourly: hourLabels.map(name => ({ name, count: hourlyMap[name] })),
      disposition: Object.entries(dispCounts).map(([name, value]) => ({ name, value }))
    };
  }, [members, rawLogs, rawCustomers]);

  if (loading && !team) return (
    <AppLayout><div className="min-h-screen flex flex-col items-center justify-center bg-gray-50/50"><div className="w-12 h-12 border-4 border-[#4b33e8] border-t-transparent rounded-full animate-spin"></div><p className="mt-4 text-gray-500 font-medium">Fetching team intelligence...</p></div></AppLayout>
  );

  if (error) return (
    <AppLayout><div className="min-h-[80vh] flex flex-col items-center justify-center p-8"><div className="w-20 h-20 bg-rose-50 rounded-full flex items-center justify-center mb-6"><i className="fi fi-rr-exclamation text-3xl text-rose-500"></i></div><h2 className="text-2xl font-bold text-gray-900 mb-2">Something went wrong</h2><p className="text-gray-500 text-center max-w-md mb-8">{error}</p><button onClick={() => router.push('/portal/dashboard')} className="px-8 py-3 bg-[#4b33e8] text-white rounded-2xl font-bold shadow-lg shadow-indigo-200 hover:scale-[1.02] active:scale-[0.98] transition-all">Go back to Dashboard</button></div></AppLayout>
  );

  return (
    <AppLayout>
      <Head><title>{team?.name || 'Team Details'} | CRM Portal</title></Head>
      <div className="container mx-auto px-4 sm:px-6 py-8 max-w-[1500px] animate-in fade-in duration-500">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 rounded-[22px] bg-gradient-to-br from-[#4b33e8] to-[#6366f1] text-white flex items-center justify-center shadow-xl shadow-indigo-100/50"><i className="fi fi-rr-users-alt text-2xl"></i></div>
            <div><div className="flex items-center gap-3 mb-1"><h1 className="text-3xl font-black text-gray-900 tracking-tight">{team?.name}</h1><span className="px-3 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase tracking-widest rounded-full border border-emerald-100">Live Analytics</span></div><p className="text-sm font-medium text-gray-400">Organization: <span className="text-gray-600 font-bold">{team?.organization?.company_name || 'Personal'}</span> • Leader: <span className="text-gray-600 font-bold text-indigo-600">@{team?.leader?.user_name || 'N/A'}</span></p></div>
          </div>
          <div className="flex bg-white/80 backdrop-blur-md p-1.5 rounded-2xl border border-gray-100 shadow-sm self-start">
            {['today', 'yesterday', 'this_week', 'this_month', 'all_time'].map((opt) => (
              <button key={opt} onClick={() => setDateFilter(opt)} className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${dateFilter === opt ? 'bg-[#4b33e8] text-white shadow-lg' : 'text-gray-400 hover:text-[#4b33e8] hover:bg-gray-50'}`}>{opt.replace('_', ' ')}</button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-10">
           {/* Summary Cards */}
           <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm group hover:border-indigo-100 transition-all"><div className="flex items-center justify-between mb-6"><div className="p-3.5 bg-indigo-50 rounded-2xl text-indigo-600"><i className="fi fi-rr-phone-call text-xl"></i></div><span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Total Volume</span></div><h3 className="text-4xl font-black text-gray-900 mb-1 tracking-tight">{Object.values(memberStatsMap).reduce((acc, s) => acc + s.totalCalls, 0).toLocaleString()}</h3><p className="text-sm text-gray-400 font-medium">Outbound Dials Recorded</p></div>
           <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm group hover:border-emerald-100 transition-all"><div className="flex items-center justify-between mb-6"><div className="p-3.5 bg-emerald-50 rounded-2xl text-emerald-600"><i className="fi fi-rr-headset text-xl"></i></div><span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Efficiency</span></div><h3 className="text-4xl font-black text-gray-900 mb-1 tracking-tight">{Object.values(memberStatsMap).length > 0 ? (Object.values(memberStatsMap).reduce((acc, s) => acc + s.connected, 0) / Object.values(memberStatsMap).reduce((acc, s) => acc + Math.max(1, s.totalCalls), 0) * 100).toFixed(1) : '0.0'}%</h3><p className="text-sm text-gray-400 font-medium">Overall Connection Rate</p></div>
           <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm group hover:border-amber-100 transition-all"><div className="flex items-center justify-between mb-6"><div className="p-3.5 bg-amber-50 rounded-2xl text-amber-600"><i className="fi fi-rr-clock text-xl"></i></div><span className="text-[10px] font-black text-amber-400 uppercase tracking-widest">Talk Time</span></div><h3 className="text-4xl font-black text-gray-900 mb-1 tracking-tight">{Math.floor(Object.values(memberStatsMap).reduce((acc, s) => acc + s.totalDurationSec, 0) / 3600)}h {Math.floor((Object.values(memberStatsMap).reduce((acc, s) => acc + s.totalDurationSec, 0) % 3600) / 60)}m</h3><p className="text-sm text-gray-400 font-medium">Cumulative Active Minutes</p></div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-10">
           <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm h-[450px]"><h3 className="font-black text-gray-900 mb-8 uppercase tracking-widest text-xs border-b border-gray-50 pb-4">Hourly Call Traffic</h3><div className="h-[320px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartsData.hourly}><defs><linearGradient id="colorCount" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4b33e8" stopOpacity={0.1}/><stop offset="95%" stopColor="#4b33e8" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F1F1" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9CA3AF', fontSize: 10, fontWeight: 700}} dy={10} /><YAxis axisLine={false} tickLine={false} tick={{fill: '#9CA3AF', fontSize: 10, fontWeight: 700}} dx={-10} /><Tooltip contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)'}} /><Area type="monotone" dataKey="count" stroke="#4b33e8" strokeWidth={4} fillOpacity={1} fill="url(#colorCount)" /></AreaChart></ResponsiveContainer></div></div>
           <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm h-[450px]"><h3 className="font-black text-gray-900 mb-8 uppercase tracking-widest text-xs border-b border-gray-50 pb-4">Outcome Distribution</h3><div className="h-[320px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={chartsData.outcome} cx="50%" cy="50%" innerRadius={80} outerRadius={110} paddingAngle={8} dataKey="value" stroke="none">{chartsData.outcome.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}</Pie><Tooltip /><Legend verticalAlign="bottom" height={36}/></PieChart></ResponsiveContainer></div></div>
        </div>

        <MemberPerformanceTable 
          members={members}
          memberStats={memberStatsMap}
          loading={loading}
          onRefresh={fetchTeamData}
          lastUpdated={new Date()}
        />
      </div>
    </AppLayout>
  );
}
